rows = [['kim', 'DB', 't1'], ['lee', 'DB', 't2'], ['kim', 'OS', 't3'], ['park', 'DB', 't1']]
COLS = ['student', 'course', 'teacher']


def holds(x, y):
    # x 값이 같은 행끼리 y 값도 같으면 True예요.
    seen = {}
    for row in rows:
        r = dict(zip(COLS, row))
        key = tuple(r[c] for c in x)
        value = tuple(r[c] for c in y)
        if seen.setdefault(key, value) != value:
            return False
    return True


def superkey(x):
    # x가 모든 열을 정하면 슈퍼키예요.
    return holds(x, COLS)


